use std::collections::{BTreeMap, HashMap, HashSet};

fn word_counts(text: &str) -> HashMap<String, usize> {
    let mut counts = HashMap::new();
    for word in text.to_lowercase().split(|c: char| !(c.is_alphabetic() || c == '\'')) {
        if !word.is_empty() {
            *counts.entry(word.to_string()).or_insert(0) += 1;
        }
    }
    counts
}

fn top_words(text: &str, n: usize) -> Vec<(String, usize)> {
    let mut pairs: Vec<(String, usize)> = word_counts(text).into_iter().collect();
    pairs.sort_by(|a, b| b.1.cmp(&a.1).then(a.0.cmp(&b.0)));
    while pairs.len() > n {
        pairs.pop();
    }
    pairs
}

fn group_anagrams(words: &[&str]) -> Vec<Vec<String>> {
    let mut index: HashMap<String, usize> = HashMap::new();
    let mut groups: Vec<Vec<String>> = Vec::new();
    for w in words {
        let mut letters: Vec<char> = w.to_lowercase().chars().collect();
        letters.sort();
        let key: String = letters.into_iter().collect();
        match index.get(&key) {
            Some(&i) => groups[i].push(w.to_string()),
            None => {
                index.insert(key, groups.len());
                groups.push(vec![w.to_string()]);
            }
        }
    }
    groups
}

fn first_unique_char(text: &str) -> Option<char> {
    let mut counts: HashMap<char, usize> = HashMap::new();
    for c in text.chars() {
        *counts.entry(c).or_default() += 1;
    }
    for c in text.chars() {
        if counts[&c] == 1 {
            return Some(c);
        }
    }
    None
}

fn letter_histogram(text: &str) -> BTreeMap<char, usize> {
    let mut hist = BTreeMap::new();
    for c in text.chars() {
        for lower in c.to_lowercase() {
            if lower.is_alphabetic() {
                *hist.entry(lower).or_insert(0) += 1;
            }
        }
    }
    hist
}

unitTests:
test("word counts", || {
    let c = word_counts("The cat and THE hat. Don't stop, don't!");
    check_eq(c["the"], 2);
    check_eq(c["don't"], 2);
    check_eq(c.len(), 6);
    check_eq(word_counts("  ...  ").len(), 0);
});

test("top words", || {
    check_eq(top_words("b a b c a b", 2), vec![("b".to_string(), 3), ("a".to_string(), 2)]);
    check_eq(top_words("x y", 5), vec![("x".to_string(), 1), ("y".to_string(), 1)]);
});

test("anagram groups", || {
    let g = group_anagrams(&["tea", "eat", "tan", "ate", "nat", "bat"]);
    check_eq(g, vec![vec!["tea", "eat", "ate"], vec!["tan", "nat"], vec!["bat"]]);
    check_eq(group_anagrams(&["Listen", "silent"]).len(), 1);
    check_eq(group_anagrams(&[]).len(), 0);
});

test("first unique", || {
    check_eq(first_unique_char("swiss"), Some('w'));
    check_eq(first_unique_char("aabb"), None);
    check_eq(first_unique_char("ééa"), Some('a'));
});

test("letter histogram", || {
    let h = letter_histogram("Hello, World!");
    check_eq(h.iter().map(|(c, n)| format!("{c}{n}")).collect::<Vec<_>>().join(" "), "d1 e1 h1 l3 o2 r1 w1");
    let set: HashSet<char> = h.keys().copied().collect();
    check(set.contains(&'w') && !set.contains(&','));
});

